-- 0003 — blog_posts table + legal + comparison content seed.
-- Seeds 186 blog post stubs (slug + title + published_at + excerpt placeholder).
-- Bodies are intentionally empty — populate via ops UI (or Nyo write_blog_post).

CREATE TABLE IF NOT EXISTS blog_posts (
  slug TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  excerpt TEXT,
  body TEXT,
  tags TEXT,                     -- JSON array
  published_at INTEGER,          -- ms epoch of intended publish date
  published INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL,
  updated_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_blog_posts_published_at ON blog_posts(published_at DESC);
CREATE INDEX IF NOT EXISTS idx_blog_posts_published    ON blog_posts(published);

